// Responsive image helpers — variants live in static/images/opt/,
// generated by scripts/gen-images.py from the photo JPG originals.
// Full-size original WebP (static/images/<stem>.webp) is the largest entry.
const WIDTHS: Record<string, number[]> = {
	hero: [400, 800, 1200, 1600]
};

/** srcset for a served photo, e.g. '/images/hero.webp'. '' if not a photo. */
export function srcsetFor(src: string): string {
	const m = src.match(/^\/images\/([^/]+)\.webp$/);
	if (!m) return '';
	const stem = m[1];
	const widths = WIDTHS[stem] ?? [400, 800, 1200];
	return widths.map((w) => `/images/opt/${stem}-${w}.webp ${w}w`).join(', ');
}
